package com.example.arcana.client;
import com.example.arcana.network.*; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.components.Button; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component;
public class SkillTreeScreen extends Screen {
 private int left,top;
 public SkillTreeScreen(){super(Component.literal("Arcana Skill Tree"));}
 protected void init(){left=width/2-170;top=height/2-110;addRenderableWidget(Button.builder(Component.literal("Attunement I"),b->ArcanaNetwork.CHANNEL.sendToServer(new UpgradeSkillPacket("attunement"))).bounds(left+18,top+115,92,28).build());addRenderableWidget(Button.builder(Component.literal("Arcane Bolt"),b->ArcanaNetwork.CHANNEL.sendToServer(new UpgradeSkillPacket("bolt_range"))).bounds(left+139,top+115,92,28).build());addRenderableWidget(Button.builder(Component.literal("Ward"),b->{}).bounds(left+260,top+115,62,28).build());addRenderableWidget(Button.builder(Component.literal("Blink"),b->{}).bounds(left+260,top+205,62,28).build());}
 public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g);int r=left+340,b=top+300;g.fill(left,top,r,b,0xE51A1420);g.fill(left+5,top+5,r-5,b-5,0xD92A2030);g.renderOutline(left,top,340,300,0xFF8B6BAD);g.drawCenteredString(font,"✦  ARCANA SKILL TREE  ✦",width/2,top+16,0xFFF0D8FF);g.drawString(font,"Skill Points: 3",r-92,top+18,0xFFFFD56B);g.drawString(font,"Core",left+153,top+52,0xFFFFFFFF);g.drawString(font,"Exploration",left+250,top+185,0xFF7EE6F4);g.drawString(font,"Defense",left+260,top+95,0xFFA8F0B2);line(g,left+64,top+95,left+185,top+95,0xFF7C5BAA);line(g,left+215,top+95,left+291,top+95,0xFF7C5BAA);line(g,left+291,top+132,left+291,top+204,0xFF7C5BAA);node(g,left+25,top+65,"✦","Attunement","+10 Mana",0xFF5BA7FF);node(g,left+146,top+65,"⚡","Arcane Bolt","+8 Range",0xFFB45CFF);node(g,left+260,top+65,"◇","Ward","0/3",0xFF82E66A);node(g,left+260,top+155,"◉","Blink","0/3",0xFF5CE7F2);g.fill(left+10,b-34,r-10,b-10,0xAA100C16);g.drawString(font,"Click a glowing node to unlock",left+18,b-27,0xFFE4D8F2);g.drawString(font,"ESC  Close",r-70,b-27,0xFFE4D8F2);super.render(g,mx,my,pt);}
 private void line(GuiGraphics g,int x1,int y1,int x2,int y2,int c){g.fill(Math.min(x1,x2),Math.min(y1,y2),Math.max(x1,x2)+2,Math.max(y1,y2)+2,c);}
 private void node(GuiGraphics g,int x,int y,String icon,String name,String sub,int color){g.fill(x,y,x+62,y+42,0xFF17131B);g.renderOutline(x,y,62,42,color);g.drawCenteredString(font,icon,x+31,y+4,color);g.drawCenteredString(font,name,x+31,y+48,0xFFFFFFFF);g.drawCenteredString(font,sub,x+31,y+60,0xFFBDB1C8);}
}
